CREATE TABLE feeding (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, animal_id BIGINT UNSIGNED NULL, financial_transaction_id BIGINT UNSIGNED NULL, recorded_by_user_id BIGINT UNSIGNED NULL, feeding_date DATE NOT NULL, feed_type VARCHAR(150) NOT NULL, quantity DECIMAL(15,2) NOT NULL, unit VARCHAR(30) NOT NULL, cost DECIMAL(15,2) NOT NULL DEFAULT 0.00, notes VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_feeding_ft (financial_transaction_id), KEY idx_feeding_animal_date (animal_id,feeding_date), CONSTRAINT chk_feeding_values CHECK (quantity > 0 AND cost >= 0), CONSTRAINT fk_feeding_animal FOREIGN KEY (animal_id) REFERENCES animals(id) ON DELETE RESTRICT, CONSTRAINT fk_feeding_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT, CONSTRAINT fk_feeding_user FOREIGN KEY (recorded_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
